<?php namespace App\Http\Controllers; use Illuminate\Support\Facades\DB; class DatabaseHealthController extends Controller { public function __invoke() { try { DB::connection()->getPdo(); return response()->json(['ok' => true, 'database' => DB::connection()->getDatabaseName()]); } catch (\Throwable) { return response()->json(['ok' => false, 'error' => 'Database unavailable'], 503); } } }
